<template><el-popover popper-class="workspace-theme workspace-popover" placement="bottom-start" :width="360" trigger="click"><template #reference><el-button class="metric-picker-button"><el-icon><Filter /></el-icon>已选择 {{ selection.length }} 项指标<el-icon><ArrowDown /></el-icon></el-button></template><div class="metric-picker-heading"><b>可选指标</b><span>{{ items.length }} 项</span></div><el-checkbox-group v-model="selection" class="metric-picker-list" @change="emit('change',$event)"><el-checkbox v-for="item in items" :key="item[valueKey]" :value="item[valueKey]">{{ item[labelKey] }}</el-checkbox></el-checkbox-group><div class="metric-picker-actions"><el-button link type="primary" @click="emit('select-all')">全选</el-button><el-button link @click="emit('invert')">反选</el-button></div></el-popover></template>
<script setup>
const selection=defineModel({type:Array,required:true})
defineProps({items:{type:Array,default:()=>[]},valueKey:{type:String,default:'metricCode'},labelKey:{type:String,default:'metricName'}})
const emit=defineEmits(['change','select-all','invert'])
</script>
<style scoped>.metric-picker-heading { display:flex; justify-content:space-between; gap:8px; margin-bottom:12px; color:var(--ui-text); font-size:12px; }.metric-picker-heading span { color:var(--ui-subtle); }.metric-picker-list { display:flex; flex-direction:column; gap:5px; max-height:320px; overflow:auto; scrollbar-width:thin; }.metric-picker-list :deep(.el-checkbox) { height:auto; min-height:28px; margin:0; }.metric-picker-list :deep(.el-checkbox__label) { white-space:normal; line-height:1.6; font-size:12px; }.metric-picker-actions { display:flex; gap:12px; padding-top:10px; margin-top:10px; border-top:1px solid var(--ui-border); }.metric-picker-button { font-size:12px; }</style>
